def is_path_exists(n, m, grid):
    # Check if the start or end cell is a wall
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return "NO"

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Helper function for DFS
    def dfs(x, y, visited):
        if x == n - 1 and y == m - 1:
            return True
        visited.add((x, y))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and (nx, ny) not in visited:
                if dfs(nx, ny, visited):
                    return True
        return False

    return "YES" if dfs(0, 0, set()) else "NO"

