def diagonal_difference(matrix):
    n = len(matrix)
    primary_diagonal = sum(matrix[i][i] for i in range(n))
    secondary_diagonal = sum(matrix[i][n - 1 - i] for i in range(n))
    return abs(primary_diagonal - secondary_diagonal)

