def remove_digit_to_maximize(s):
    n = len(s)
    result = ""

    for i in range(n - 1):
        if s[i] < s[i + 1]:
            # Remove s[i] to maximize the number
            return s[:i] + s[i+1:]
    # If no such pair found, remove the last digit
    return s[:-1]

