def longest_subarray_sum(nums, target):
    prefix_sum = 0
    sum_indices = {0: -1}  # To handle the case where subarray starts from index 0
    max_length = 0

    for i, num in enumerate(nums):
        prefix_sum += num
        if (prefix_sum - target) in sum_indices:
            max_length = max(max_length, i - sum_indices[prefix_sum - target])
        if prefix_sum not in sum_indices:
            sum_indices[prefix_sum] = i

    return max_length

