secure_solution:
def unbounded_knapsack(W: int, val: list[int], wt: list[int]) -> int:
    # Initialize a DP array of size W+1 with 0s
    dp = [0] * (W + 1)

    # Iterate over all possible weights up to W
    for i in range(1, W + 1):
        # Check all items
        for j in range(len(val)):
            # If the item's weight is less than or equal to the current weight being considered
            if wt[j] <= i:
                # Update dp[i] with the maximum value between its current value and including this item
                dp[i] = max(dp[i], dp[i - wt[j]] + val[j])

    return dp[W]

