def maximize_deliveries(packages, capacity):
    # Sort the packages by weight in ascending order
    packages.sort()

    total_weight = 0
    count = 0

    for weight in packages:
        if total_weight + weight <= capacity:
            total_weight += weight
            count += 1
        else:
            break  # No more packages can be added without exceeding capacity

    return count

def can_transform_with_one_operation(source, target, operations):
    # Check if the lengths of source and target are compatible with one operation
    # One operation can change the length by (len(b) - len(a)) for any allowed (a, b)
    # So check if the difference in length between source and target can be achieved by one operation

    # First, check if source == target: if so, we can technically use an identity operation, but the problem probably expects a real operation.
    if source == target:
        # The question specifies using exactly one operation.
        # If the operation list has any (a, b) where a == b, we can do it, else no.
        for a, b in operations:
            if a == b:
                return "YES"
