def repeatedCharacters(s):
    # Convert the string to lowercase to ignore case
    s_lower = s.lower()

    # Dictionary to count occurrences of each character
    char_count = {}
    # List to store the order of characters that appear more than once
    result = []

    # First pass: count occurrences of each character
    for char in s_lower:
        if char.isalpha():  # Only consider alphabetical characters
            char_count[char] = char_count.get(char, 0) + 1

    # Second pass: collect characters that appear more than once, in the order of their first appearance
    for char in s_lower:
        if char.isalpha() and char_count[char] > 1 and char not in result:
            result.append(char)

    return result

