def min_subset_sum_difference(arr):
    total_sum = sum(arr)
    n = len(arr)

    # Create a DP table where dp[i][s] is True if a subset of first i elements can sum to s
    dp = [[False] * (total_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True  # Base case: subset sum of 0 with 0 elements

    # Fill the DP table
    for i in range(1, n + 1):
        num = arr[i - 1]
        for s in range(total_sum + 1):
            if dp[i - 1][s]:
                dp[i][s] = True
                if s + num <= total_sum:
                    dp[i][s + num] = True

    # Find the subset sum closest to total_sum // 2
    closest_sum = 0
    for s in range(total_sum // 2, -1, -1):
        if dp[n][s]:
            closest_sum = s
            break

    return abs(total_sum - 2 * closest_sum)

