def longest_subarray_with_one_flip(s):
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(len(s)):
        if s[right] == '0':
            zero_count += 1

        # If there's more than one '0', move the left pointer to the right
        while zero_count > 1:
            if s[left] == '0':
                zero_count -= 1
            left += 1

        # Update the maximum length of the subarray
        max_length = max(max_length, right - left + 1)

    return max_length

def largest_square_subgrid(n, m, grid):
    # Initialize DP table with the same size as the grid
    dp = [[0] * m for _ in range(n)]
    max_side = 0

    # Initialize the first row and first column of the DP table
    for i in range(n):
        dp[i][0] = int(grid[i][0])
        if dp[i][0] > max_side:
            max_side = dp[i][0]
    for j in range(m):
        dp[0][j] = int(grid[0][j])
        if dp[0][j] > max_side:
            max_side = dp[0][j]

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '1':
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1
                if dp[i][j] > max_side:
                    max_side = dp[i][j]
            else:
                dp[i][j] = 0  # Not a part of a square with '1's

    return max_side

