from collections import deque

def min_steps_in_maze(grid):
    m, n = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return -1  # Start or end is blocked

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    visited = [[False] * n for _ in range(m)]
    queue = deque([(0, 0, 0)])  # (row, col, steps)
    visited[0][0] = True

    while queue:
        r, c, steps = queue.popleft()
        if r == m - 1 and c == n - 1:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and not visited[nr][nc] and grid[nr][nc] == 0:
                visited[nr][nc] = True
                queue.append((nr, nc, steps + 1))

    return -1  # If destination is unreachable

def knapsack(n, W, items):
    # Initialize the DP array with size W+1, all set to 0
    dp = [0] * (W + 1)

    # Iterate over each gemstone
    for weight, value in items:
        # Go backward to ensure each gemstone is only used once
        for w in range(W, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    # The maximum value is at dp[W], which is the maximum value for weight <= W
    return dp[W]

