def is_rotation_90(A: list[list[int]], B: list[list[int]]) -> bool:
    n = len(A)

    # Check if dimensions match
    if n != len(B):
        return False

    # Create a 90-degree clockwise rotation of A
    rotated_A = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            rotated_A[j][n - 1 - i] = A[i][j]

    # Compare rotated matrix with B
    return rotated_A == B

