def can_form_consecutive(nums, k):
    n = len(nums)
    if k == 0 or k > n:
        return False

    for i in range(n - k + 1):
        subarray = nums[i:i + k]
        unique_elements = set(subarray)
        min_val = min(subarray)
        max_val = max(subarray)

        if max_val - min_val == k - 1 and len(unique_elements) == k:
            return True

    return False

