def max_sum_increasing_subsequence(arr):
    n = len(arr)
    dp = [0] * n  # dp[i] will store the max sum of increasing subsequence ending at index i
    prev = [ -1 ] * n  # To reconstruct the subsequence

    for i in range(n):
        dp[i] = arr[i]  # Initialize with the value itself
        for j in range(i):
            if arr[j] < arr[i] and dp[j] + arr[i] > dp[i]:
                dp[i] = dp[j] + arr[i]
                prev[i] = j  # Keep track of the previous index in the subsequence

    # Find the index of the maximum sum
    max_sum_index = 0
    for i in range(1, n):
        if dp[i] > dp[max_sum_index]:
            max_sum_index = i

    # Reconstruct the subsequence
    subsequence = []
    i = max_sum_index
    while i != -1:
        subsequence.append(arr[i])
        i = prev[i]

    return dp[max_sum_index], subsequence[::-1]

from collections import deque

def min_moves_to_water(grid):
    if not grid or not grid[0]:
        return -1

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    # Find the start position
    start = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
                break
        if start:
            break

    if not start:
        return -1  # No start position found

    visited = [[False] * cols for _ in range(rows)]
    queue = deque()
    queue.append((start[0], start[1], 0))  # (row, col, moves)
    visited[start[0]][start[1]] = True

    while queue:
        r, c, moves = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                visited[nr][nc] = True
                if grid[nr][nc] == 'W':
                    return moves + 1
                queue.append((nr, nc, moves + 1))

    return -1  # No water cell reachable

