def count_subarrays(arr, threshold, size):
    n = len(arr)
    if size > n:
        return 0  # No subarrays of length greater than the array length

    current_sum = sum(arr[:size])
    count = 1 if current_sum >= threshold else 0

    for i in range(size, n):
        current_sum += arr[i] - arr[i - size]
        if current_sum >= threshold:
            count += 1

    return count

