def maxProfit(prices, fee):
    if not prices:
        return 0

    cash, hold = 0, -prices[0]

    for price in prices[1:]:
        # Update cash: max of holding cash or selling the stock
        cash = max(cash, hold + price - fee)
        # Update hold: max of holding stock or buying the stock
        hold = max(hold, cash - price)

    return cash

def matching_words(words, queries):
    results = []
    for prefix, suffix in queries:
        count = 0
        for word in words:
            if word.startswith(prefix) and word.endswith(suffix):
                count += 1
        results.append(count)
    return results

