def integer_partition(n: int) -> int:
    # Initialize a 2D DP array with (n+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: there is exactly one way to partition 0
    for j in range(n + 1):
        dp[0][j] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j > i:
                dp[i][j] = dp[i][i]
            else:
                dp[i][j] = dp[i][j - 1] + dp[i - j][j]

    return dp[n][n]

