def find_median_sorted_arrays(nums1: list[int], nums2: list[int]) -> float:
    # Ensure nums1 is the smaller array to optimize binary search
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1

    n, m = len(nums1), len(nums2)
    low, high = 0, n

    while low <= high:
        partition_nums1 = (low + high) // 2
        partition_nums2 = (n + m + 1) // 2 - partition_nums1

        # Edge cases: when partition is at the beginning or end of nums1
        max_left_nums1 = float('-inf') if partition_nums1 == 0 else nums1[partition_nums1 - 1]
        min_right_nums1 = float('inf') if partition_nums1 == n else nums1[partition_nums1]

        max_left_nums2 = float('-inf') if partition_nums2 == 0 else nums2[partition_nums2 - 1]
        min_right_nums2 = float('inf') if partition_nums2 == m else nums2[partition_nums2]

        # Check if the current partition is valid
        if max_left_nums1 <= min_right_nums2 and max_left_nums2 <= min_right_nums1:
            # The combined array has even length
            if (n + m) % 2 == 0:
                return (max(max_left_nums1, max_left_nums2) + min(min_right_nums1, min_right_nums2)) / 2
            # The combined array has odd length
            else:
                return float(max(max_left_nums1, max_left_nums2))
        elif max_left_nums1 > min_right_nums2:
            # Move partition to the left in nums1
            high = partition_nums1 - 1
        else:
            # Move partition to the right in nums1
            low = partition_nums1 + 1

