def max_unique_sum_subarray(T, test_cases):
    results = []

    for test_case in test_cases:
        N, E = test_case
        left = 0
        max_sum = 0
        current_sum = 0
        seen = {}

        for right in range(N):
            val = E[right]

            if val in seen and seen[val] >= left:
                # Remove elements from the left up to the duplicate element
                while left <= seen[val]:
                    current_sum -= E[left]
                    left += 1

            seen[val] = right
            current_sum += val
            max_sum = max(max_sum, current_sum)

        results.append(max_sum)

    return results

