def shortest_sequence_to_return_to_origin(n, commands):
    # Calculate the final position after executing all commands
    position = 0
    for cmd in commands:
        if cmd == 'R':
            position += 1
        else:
            position -= 1

    # If already at position 0, return an empty string
    if position == 0:
        return ""

    # Otherwise, add 'R' if position is negative (need to move right)
    # or 'L' if position is positive (need to move left)
    return 'R' * (-position) if position < 0 else 'L' * position

