def can_split_grid(n: int, m: int, grid: List[List[int]]) -> bool:
    total_sum = sum(sum(row) for row in grid)

    # If the total sum is odd, it's impossible to split into two equal parts
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    prefix_sums = [[0] * (m + 1) for _ in range(n + 1)]

    # Compute prefix sums
    for i in range(n):
        for j in range(m):
            prefix_sums[i + 1][j + 1] = grid[i][j] + prefix_sums[i][j + 1] + prefix_sums[i + 1][j] - prefix_sums[i][j]

    # Try vertical splits
    for i in range(1, n):
        for j in range(1, m + 1):
            # Calculate sum of top part
            top_sum = prefix_sums[i][j] - prefix_sums[0][j]
            if top_sum == target:
                return True

    # Try horizontal splits
    for j in range(1, m):
        for i in range(1, n + 1):
            # Calculate sum of left part
            left_sum = prefix_sums[i][j] - prefix_sums[i][0]
            if left_sum == target:
                return True

    return False

