def is_subarray_sum_divisible(n, k, A, queries):
    # Compute prefix sums modulo k
    prefix_mod = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_mod[i] = (prefix_mod[i - 1] + A[i - 1]) % k

    # Process each query
    results = []
    for L, R in queries:
        # Sum from A[L-1] to A[R-1] in 0-based indexing
        # is (prefix_mod[R] - prefix_mod[L-1]) % k
        if (prefix_mod[R] - prefix_mod[L - 1]) % k == 0:
            results.append("YES")
        else:
            results.append("NO")

    return results

