import itertools

def max_combination_sum(collection):
    if not collection:
        return ([], 0)

    max_sum = float('-inf')
    best_combination = []

    # Generate all non-empty combinations
    for i in range(1, len(collection) + 1):
        for combo in itertools.combinations(collection, i):
            current_sum = sum(combo)
            if current_sum > max_sum:
                max_sum = current_sum
                best_combination = list(combo)

    # If the maximum sum is still negative, return the empty list and 0
    if max_sum < 0:
        return ([], 0)

    return (best_combination, max_sum)

