from collections import deque
from typing import List

def word_ladder(begin: str, end: str, word_list: List[str]) -> int:
    word_set = set(word_list)

    # If the end word is not in the word_set, it's impossible to reach
    if end not in word_set:
        return 0

    # Initialize the queue for BFS
    queue = deque([(begin, 1)])

    while queue:
        current_word, length = queue.popleft()

        # If we've reached the target word, return the current length
        if current_word == end:
            return length

        # Generate all possible one-character variations
        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                next_word = current_word[:i] + c + current_word[i+1:]
                if next_word in word_set:
                    queue.append((next_word, length + 1))
                    word_set.remove(next_word)  # Avoid revisiting

    # If we've exhausted all possibilities and haven't reached the end word
    return 0

