from typing import List

def reconstruct_word(scrambled: str, dictionary: List[str]) -> str:
    # Sort the scrambled word to get its canonical form
    sorted_scrambled = ''.join(sorted(scrambled))

    # Iterate through the dictionary and compare sorted versions of each word
    for word in dictionary:
        if ''.join(sorted(word)) == sorted_scrambled:
            return word

    # If no match is found, return an empty string
    return ""

