from typing import List

def longest_subarray_with_sum(nums: List[int], target_sum: int) -> int:
    prefix_sum_map = {}
    prefix_sum = 0
    max_length = 0
    prefix_sum_map[0] = -1  # To handle the case where the subarray starts from index 0

    for index, num in enumerate(nums):
        prefix_sum += num
        # Check if prefix_sum - target_sum exists in the map
        if (prefix_sum - target_sum) in prefix_sum_map:
            max_length = max(max_length, index - prefix_sum_map[prefix_sum - target_sum])
        # Store the first occurrence of the prefix_sum
        if prefix_sum not in prefix_sum_map:
            prefix_sum_map[prefix_sum] = index

    return max_length

