def is_consecutive_sequence(arr):
    if not arr:
        return False

    # Sort the array
    arr_sorted = sorted(arr)

    # Check if the difference between the maximum and minimum is equal to the length minus 1
    # and that all elements are unique (to avoid duplicates)
    if len(set(arr)) != len(arr):
        return False

    return arr_sorted[-1] - arr_sorted[0] == len(arr) - 1

