def knapsack_max_value(values, weights, W):
    n = len(values)
    # dp[i][w] will represent the maximum value achievable using first i items and weight w
    dp = [[0] * (W + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(W + 1):
            # If the current item's weight is more than the current capacity, skip it
            if weights[i - 1] > w:
                dp[i][w] = dp[i - 1][w]
            else:
                # Either include the item or exclude it, take the maximum
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])

    return dp[n][W]

