def partition_lengths(nums):
    if not nums:
        return []

    result = []
    current_value = nums[0]
    count = 1

    for num in nums[1:]:
        if num == current_value:
            count += 1
        else:
            result.append(count)
            current_value = num
            count = 1

    # Append the last group
    result.append(count)
    return result

