def longest_palindromic_subsequence(word):
    n = len(word)
    # Initialize a 2D DP table with all 0s
    dp = [[0] * n for _ in range(n)]

    # Every single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

