def count(coins, value):
    # Initialize DP array with 0s
    dp = [0] * (value + 1)
    dp[0] = 1  # Base case: one way to make 0 change

    # Iterate through each coin
    for coin in coins:
        # Update the DP array for each amount from coin to value
        for i in range(coin, value + 1):
            dp[i] += dp[i - coin]

    return dp[value]

