def three_sum(nums, target):
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        # Skip duplicate elements to ensure distinct elements
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, n - 1

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]

            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False

