def buddy_strings(s, goal):
    if len(s) != len(goal):
        return False

    if s == goal:
        # Check if there's at least one character that appears at least twice
        return len(set(s)) < len(s)

    # Find the indices where characters differ
    diff_indices = []
    for i in range(len(s)):
        if s[i] != goal[i]:
            diff_indices.append(i)
            if len(diff_indices) > 2:
                return False  # More than two differing positions

    # Check if swapping the two differing characters makes s equal to goal
    return len(diff_indices) == 2 and s[diff_indices[0]] == goal[diff_indices[1]] and s[diff_indices[1]] == goal[diff_indices[0]]

