from typing import List

def max_histogram_area(building_heights: List[int]) -> int:
    if not building_heights:
        return 0

    for height in building_heights:
        if height < 0:
            raise ValueError("all building heights must be non-negative integers")

    stack = []
    max_area = 0
    heights = building_heights + [0]  # Add a sentinel to handle remaining elements in the stack

    for i, height in enumerate(heights):
        while stack and heights[stack[-1]] > height:
            h = heights[stack.pop()]
            w = i if not stack else i - stack[-1] - 1
            max_area = max(max_area, h * w)
        stack.append(i)

    return max_area

