secure_solution:
def decode_string(s: str) -> str:
    stack = []
    result = ''
    current_number = 0

    for char in s:
        if char.isdigit():
            current_number = current_number * 10 + int(char)
        elif char == '[':
            # Push the current result and current number to stack
            stack.append((result, current_number))
            result = ''
            current_number = 0
        elif char == ']':
            # Pop from the stack
            prev_result, num = stack.pop()
            result = prev_result + num * result
        else:
            result += char

    return result

