def count_unfavorable_pairs(n, permutation):
    from bisect import bisect_right

    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, index, delta):
            while index <= self.n:
                self.tree[index] += delta
                index += index & -index

        def query(self, index):
            res = 0
            while index > 0:
                res += self.tree[index]
                index -= index & -index
            return res

    # Compress the permutation values to 1-based index
    # Since permutation is a permutation of 1..n, we can use the values directly
    max_val = n
    ft = FenwickTree(max_val)
    inversions = 0

    for i in reversed(permutation):
        # Count of elements <= i-1 encountered so far
        inversions += ft.query(i - 1)
        ft.update(i, 1)

    return inversions

