def optimized_bubble_sort(arr: List[int], simulation: bool = False) -> List[int]:
    n = len(arr)
    if n <= 1:
        return arr

    # Outer loop for each pass
    for i in range(n):
        swapped = False

        # Inner loop for comparisons
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                # Swap elements
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True

                # If simulation is enabled, print the current state
                if simulation:
                    print(f"iteration {i} : {' '.join(map(str, arr))}")

        # If no swaps were made in this pass, the array is sorted
        if not swapped:
            break

    return arr

