    digits = []
    specials = []

    for char in s:
        if char.isalpha():
            letters.append(char)
        elif char.isdigit():
            digits.append(char)
        else:
            specials.append(char)

    # Sort letters: uppercase first, then lowercase
    letters.sort(key=lambda x: (x.islower(), x))

    # Sort digits numerically
    digits.sort()

    # Special characters retain their original order

    # Combine the results
    return ''.join(letters + digits + specials)

def is_path_possible(N, M, grid):
    # Initialize a DP table with the same dimensions as grid
    dp = [[False for _ in range(M)] for _ in range(N)]

    # Start point
    if grid[0][0] == '1':
        return 0

    dp[0][0] = True

    # Fill first row
    for j in range(1, M):
        if grid[0][j] == '0' and dp[0][j - 1]:
            dp[0][j] = True
        else:
            break  # No path if a blockage is encountered

    # Fill first column
    for i in range(1, N):
        if grid[i][0] == '0' and dp[i - 1][0]:
            dp[i][0] = True
        else:
            break  # No path if a blockage is encountered

    # Fill the rest of the table
    for i in range(1, N):
        for j in range(1, M):
            if grid[i][j] == '0' and (dp[i - 1][j] or dp[i][j - 1]):
                dp[i][j] = True

    return 1 if dp[N - 1][M - 1] else 0

