def find_paths(grid):
    n = len(grid)

    # If the start or end cell is blocked, no path is possible
    if grid[0][0] == 1 or grid[n-1][n-1] == 1:
        return 0

    # Memoization table
    memo = [[-1 for _ in range(n)] for _ in range(n)]

    def dfs(i, j):
        # If we reach the bottom-right corner, return 1 path
        if i == n - 1 and j == n - 1:
            return 1

        # If already computed, return the stored value
        if memo[i][j] != -1:
            return memo[i][j]

        paths = 0

        # Move down
        if i + 1 < n and grid[i+1][j] == 0:
            paths += dfs(i+1, j)

        # Move right
        if j + 1 < n and grid[i][j+1] == 0:
            paths += dfs(i, j+1)

        # Store the result in memo table
        memo[i][j] = paths
        return paths

    return dfs(0, 0)

