def findCheapestPrice(n, flights, src, dst, k):
    # Initialize a DP array to store minimum cost to reach each city with at most i stops
    dist = [float('inf')] * n
    dist[src] = 0

    # Iterate k + 1 times because with at most k stops, we can have at most k+1 flights
    for _ in range(k + 1):
        temp_dist = dist[:]
        for frm, to, price in flights:
            if dist[frm] != float('inf') and dist[frm] + price < temp_dist[to]:
                temp_dist[to] = dist[frm] + price
        dist = temp_dist

    return dist[dst] if dist[dst] != float('inf') else -1

