def group_files_by_type(files):
    file_groups = {}

    for file in files:
        # Split the file name and extension
        if '.' in file:
            _, ext = file.rsplit('.', 1)
            ext = ext.lower()  # Make the extension case-insensitive
        else:
            ext = ''  # No extension

        # Add to the corresponding group
        if ext not in file_groups:
            file_groups[ext] = []
        file_groups[ext].append(file)

    # Sort each group lexicographically, ignoring case
    for ext in file_groups:
        file_groups[ext].sort(key=lambda x: x.lower())

    return file_groups

