secure_solution:
def largest_rectangle_area(heights: list[int]) -> int:
    n = len(heights)
    left = [0] * n
    right = [0] * n

    stack = []

    # Find the previous smaller element for each building
    for i in range(n):
        while stack and heights[stack[-1]] >= heights[i]:
            stack.pop()
        if stack:
            left[i] = stack[-1]
        else:
            left[i] = -1
        stack.append(i)

    stack = []

    # Find the next smaller element for each building
    for i in range(n - 1, -1, -1):
        while stack and heights[stack[-1]] >= heights[i]:
            stack.pop()
        if stack:
            right[i] = stack[-1]
        else:
            right[i] = n
        stack.append(i)

    max_area = 0
    for i in range(n):
        area = heights[i] * (right[i] - left[i] - 1)
        max_area = max(max_area, area)

    return max_area

