def min_cost_climbing_stairs(cost):
    n = len(cost)

    # Base cases: cost to reach step 0 or 1
    if n == 0:
        return 0
    if n == 1:
        return cost[0]

    # Initialize dp array
    dp = [0] * n
    dp[0] = cost[0]
    dp[1] = cost[1]

    # Fill dp array
    for i in range(2, n):
        dp[i] = cost[i] + min(dp[i - 1], dp[i - 2])

    # The top of the staircase is one step beyond the last step
    return min(dp[-1], dp[-2])

