def checkValidString(s: str) -> bool:
    low = 0
    high = 0

    for char in s:
        if char == '(':
            low += 1
            high += 1
        elif char == ')':
            low -= 1
            high -= 1
        elif char == '*':
            low -= 1  # consider * as ')'
            high += 1  # consider * as '('

        # If high goes below 0, it's invalid
        if high < 0:
            return False

        # Ensure low doesn't go below 0
        low = max(low, 0)

    return low == 0

