    if k > len(arr) or k <= 0:
        return 0

    current_sum = sum(arr[:k])  # Sum of the first window
    max_sum = current_sum

    for i in range(k, len(arr)):
        current_sum += arr[i] - arr[i - k]  # Slide the window
        max_sum = max(max_sum, current_sum)

    return max_sum

