def count_paths(n, k, obstacles):
    # Convert obstacles to a set for O(1) lookup
    obstacle_set = set((r - 1, c - 1) for r, c in obstacles)

    # If start or end is blocked
    if (0, 0) in obstacle_set or (n - 1, n - 1) in obstacle_set:
        return 0

    # Initialize dp table
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1

    # Fill the dp table
    for i in range(n):
        for j in range(n):
            if (i, j) in obstacle_set:
                dp[i][j] = 0
                continue
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]

    return dp[n - 1][n - 1]

