def longest_common_subsequence(s1: str, s2: str) -> int:
    # Get the lengths of the two input strings
    m, n = len(s1), len(s2)

    # Create a 2D DP table of size (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                # If characters match, take diagonal value + 1
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                # Otherwise, take the max of the top or left value
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The result is in the bottom-right corner of the table
    return dp[m][n]

def longest_subsequence_by_sum(arr: list[int], target_sum: int) -> tuple[int, list[int]]:
    if not arr or target_sum < 0:
        return (0, [])

    n = len(arr)
    left = 0
    current_sum = 0
    max_length = 0
    max_subsequence = []

    for right in range(n):
        current_sum += arr[right]

        # If current_sum exceeds the target, move the left pointer to reduce the sum
        while current_sum > target_sum:
            current_sum -= arr[left]
            left += 1

        # Update max subsequence if the current window is longer
        if right - left + 1 > max_length:
            max_length = right - left + 1
            max_subsequence = arr[left:right + 1]

    return (max_length, max_subsequence)

