from typing import List

def is_diagonal_pattern(matrix: List[List[int]]) -> bool:
    if not matrix or not matrix[0]:
        return True  # Empty matrix is considered to follow the pattern

    rows, cols = len(matrix), len(matrix[0])

    # Check diagonals starting from the first column
    for col in range(cols):
        start_row = 0
        current_value = matrix[start_row][col]
        row, col = start_row, col
        while row < rows and col < cols:
            if matrix[row][col] != current_value:
                return False
            row += 1
            col += 1

    # Check diagonals starting from the first row (excluding the first element already checked)
    for row in range(1, rows):
        start_col = 0
        current_value = matrix[row][start_col]
        row, col = row, start_col
        while row < rows and col < cols:
            if matrix[row][col] != current_value:
                return False
            row += 1
            col += 1

    return True

