def max_candies(T, test_cases):
    results = []
    for n, candies in test_cases:
        if n == 0:
            results.append(0)
            continue
        prev, curr = 0, 0
        for i in range(n):
            next_val = max(curr, prev + candies[i])
            prev, curr = curr, next_val
        results.append(curr)
    return results

