        for j in range(m):
            if grid[i][j] == '.':
                # If it's a safe cell, check the neighboring cells
                if i == 0 or j == 0:
                    dp[i][j] = 1  # Edge of the grid, max square size is 1
                else:
                    dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1
