def min_path_sum(grid):
    m = len(grid)
    n = len(grid[0])

    # Initialize a DP table with infinity
    dp = [[float('inf')] * n for _ in range(m)]

    # If the start or end cell is blocked, return -1
    if grid[0][0] == -1 or grid[m-1][n-1] == -1:
        return -1

    # Starting point
    dp[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == -1:
            break
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] == -1:
            break
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == -1:
