def num_ones_in_submatrix(grid, queries):
    if not grid or not queries:
        return []

    m, n = len(grid), len(grid[0])

    # Step 1: Create prefix sum matrix
    prefix = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m):
        for j in range(n):
            prefix[i+1][j+1] = grid[i][j] + prefix[i][j+1] + prefix[i+1][j] - prefix[i][j]

    # Step 2: Process each query
    result = []
    for r1, c1, r2, c2 in queries:
        # Convert to 1-indexed for prefix sum logic
        sum_submatrix = prefix[r2+1][c2+1] - prefix[r1][c2+1] - prefix[r2+1][c1] + prefix[r1][c1]
        result.append(sum_submatrix)

    return result

import heapq

def find_kth_largest(nums, k):
    # Use a min-heap of size k to keep the k largest elements
    # The smallest of these k elements will be the k-th largest in the list
    min_heap = []

    for num in nums:
        heapq.heappush(min_heap, num)
        if len(min_heap) > k:
            heapq.heappop(min_heap)

    return min_heap[0]

