from typing import List, Tuple

def improved_selection_sort(arr: List[int], simulation: bool = False) -> Tuple[List[int], int]:
    """
    Sorts an array using improved selection sort and counts the number of swaps.

    Parameters:
    arr (List[int]): The list to be sorted.
    simulation (bool): If True, print the array at each iteration of the outer loop.

    Returns:
    Tuple[List[int], int]: The sorted list and the number of swaps performed.
    """
    n = len(arr)
    swaps = 0

    for i in range(n):
        # Find the minimum element in the remaining unsorted array
        min_index = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_index]:
                min_index = j

        # If the array is already sorted, break early
        if min_index == i:
            if i == 0:
                # Check if the array is already sorted
                is_sorted = True
                for k in range(n - 1):
                    if arr[k] > arr[k + 1]:
                        is_sorted = False
                        break
                if is_sorted:
                    break
            else:
                # If the current i-th element is in place, check for sortedness
                is_sorted = True
                for k in range(i, n - 1):
                    if arr[k] > arr[k + 1]:
                        is_sorted = False
                        break
                if is_sorted:
                    break

        # Swap the found minimum element with the first element of the unsorted part
        if min_index != i:
            arr[i], arr[min_index] = arr[min_index], arr[i]
            swaps += 1

        # Print the array if simulation is requested
        if simulation:
            print(f"iteration {i} : {' '.join(map(str, arr))}")

    return arr, swaps

