from typing import List

def canPartition(nums: List[int]) -> bool:
    total_sum = sum(nums)

    # If total sum is odd, it's not possible to partition
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible with an empty subset

    for num in nums:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return dp[target]

