from typing import Dict, List

def depth_first_search(graph: Dict[int, List[int]], start_vertex: int) -> List[int]:
    if not graph or start_vertex not in graph:
        return []

    visited = set()
    stack = [start_vertex]
    result = []

    while stack:
        vertex = stack.pop()
        if vertex not in visited:
            visited.add(vertex)
            result.append(vertex)
            # Add neighbors in reverse order to maintain the same order as recursive DFS
            for neighbor in reversed(graph[vertex]):
                if neighbor not in visited:
                    stack.append(neighbor)

    return result

