def can_rearrange_odd_even(T, test_cases):
    results = []
    for case in test_cases:
        N, arr = case
        even_count = 0
        odd_count = 0

        for num in arr:
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

        # In 1-based indexing:
        # Positions 1, 3, 5, ... (odd indices) should be odd
        # Positions 2, 4, 6, ... (even indices) should be even
        # Number of odd positions = (N + 1) // 2
        # Number of even positions = N // 2

        odd_positions = (N + 1) // 2
        even_positions = N // 2

        if odd_count >= odd_positions and even_count >= even_positions:
            results.append("YES")
        else:
            results.append("NO")

    return results

