def max_tasks_within_deadline(n, T, durations):
    # Sort durations to prioritize shorter tasks
    durations.sort()

    total_time = 0
    count = 0

    for duration in durations:
        if total_time + duration <= T:
            total_time += duration
            count += 1
        else:
            break  # No more tasks can be added without exceeding the deadline

    return count

