def min_abs_difference(n, sequence):
    total_sum = sum(sequence)
    current_sum = 0
    min_diff = float('inf')

    for i in range(n - 1):
        current_sum += sequence[i]
        diff = abs(total_sum - 2 * current_sum)
        if diff < min_diff:
