def longest_common_substring(s1, s2):
    m = len(s1)
    n = len(s2)

    # Initialize a 2D DP table of (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    max_len = 0  # Length of the longest common substring
    end_index = 0  # End index of the longest common substring in s1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > max_len:
                    max_len = dp[i][j]
                    end_index = i

    # Extract the substring from s1 using the max length and end index
    return s1[end_index - max_len:end_index]

