import math

def smallest_max_distance(n, angles):
    # Sort the angles
    angles_sorted = sorted(angles)

    max_gap = 0.0

    # Calculate differences between adjacent angles
    for i in range(1, n):
        gap = angles_sorted[i] - angles_sorted[i - 1]
        if gap > max_gap:
            max_gap = gap

    # Calculate the wrap-around gap (between last and first)
    wrap_gap = 360 - angles_sorted[-1] + angles_sorted[0]
    if wrap_gap > max_gap:
        max_gap = wrap_gap

    # Convert the maximum angular gap to radians
    return math.radians(max_gap)

