def find_tasks_for_xp(n, k, t, xp_list):
    def backtrack(start, path, current_sum):
        if len(path) == k:
            if current_sum == t:
                return path.copy()
            return None

        for i in range(start, n):
            if current_sum + xp_list[i] > t:
                continue  # Early pruning to avoid unnecessary computation
            path.append(i)
            result = backtrack(i + 1, path, current_sum + xp_list[i])
            if result is not None:
                return result
            path.pop()

        return None

    result = backtrack(0, [], 0)
    return result if result else []

