from collections import Counter

def min_swaps_to_identical(arr1, arr2):
    # Check if total element counts are even
    combined = arr1 + arr2
    count = Counter(combined)
    for val in count.values():
        if val % 2 != 0:
            return -1

    # Count mismatched positions
    mismatches = []
    for i in range(len(arr1)):
        if arr1[i] != arr2[i]:
            mismatches.append(i)

    # The number of mismatched positions must be even
    if len(mismatches) % 2 != 0:
        return -1

    # Each pair of mismatches requires one swap
    return len(mismatches) // 2

