def schedule_meetings(meetings):
    # Sort the meetings based on their end times
    sorted_meetings = sorted(meetings, key=lambda x: x[1])

    scheduled = []

    for meeting in sorted_meetings:
        # If the scheduled list is empty or the current meeting starts after the last scheduled meeting ends
        if not scheduled or meeting[0] >= scheduled[-1][1]:
            scheduled.append(meeting)

    return scheduled

