from collections import deque

def minimum_moves(n, board):
    if board[0][0] == 1 or board[n-1][n-1] == 1:
        return -1  # Start or end is blocked

    visited = [[False] * n for _ in range(n)]
    queue = deque()
    queue.append((0, 0, 0))  # (row, col, moves)
    visited[0][0] = True

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while queue:
        row, col, moves = queue.popleft()

        if row == n - 1 and col == n - 1:
            return moves

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n and not visited[new_row][new_col] and board[new_row][new_col] == 0:
                visited[new_row][new_col] = True
                queue.append((new_row, new_col, moves + 1))

    return -1

