def longest_zero_sum_subarray(arr):
    prefix_sum_map = {0: -1}  # Store first occurrence of prefix sums
    max_length = 0
    current_sum = 0

    for i, num in enumerate(arr):
        current_sum += num
        if current_sum in prefix_sum_map:
            # If current_sum exists, update max_length
            max_length = max(max_length, i - prefix_sum_map[current_sum])
        else:
            # Store the first occurrence of current_sum
            prefix_sum_map[current_sum] = i

    return max_length

def max_dessert_combination(n, desserts, dessert_types):
    # Initialize max_spicy and max_sweet to store the maximum prices for each type
    max_spicy = -1
    max_sweet = -1

    # Iterate through each dessert to find the max prices
    for i in range(n):
        if dessert_types[i] == 'S':
            if desserts[i] > max_spicy:
                max_spicy = desserts[i]
        elif dessert_types[i] == 'W':
            if desserts[i] > max_sweet:
                max_sweet = desserts[i]

    # Check if both types are present
    if max_spicy == -1 or max_sweet == -1:
        return -1
    else:
        return max_spicy + max_sweet

