def tribonacci_number(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1 or n == 2:
        return 1

    # Initial values for T0, T1, T2
    a, b, c = 0, 1, 1

    # Iterate from 3 to n to compute the Tribonacci number
    for _ in range(3, n + 1):
        next_val = a + b + c
        a, b, c = b, c, next_val

    return c

def findLength(arr, n, target_sum):
    prefix_sum = 0
    prefix_map = {}
    max_length = 0

    # Initialize the prefix map with prefix_sum 0 at index -1
    prefix_map[0] = -1

    for i in range(n):
        prefix_sum += arr[i]

        # If (prefix_sum - target_sum) exists in the map, update max_length
        if (prefix_sum - target_sum) in prefix_map:
            max_length = max(max_length, i - prefix_map[prefix_sum - target_sum])

        # Store the first occurrence of the current prefix_sum
        if prefix_sum not in prefix_map:
            prefix_map[prefix_sum] = i

    return max_length

