from collections import Counter

def frequency_sort(arr: list[int]) -> list[int]:
    # Count the frequency of each element
    freq = Counter(arr)

    # Track the first occurrence index of each element
    first_occurrence = {}
    for idx, num in enumerate(arr):
        if num not in first_occurrence:
            first_occurrence[num] = idx

    # Sort the array with custom key: (-frequency, first_occurrence_index)
    sorted_arr = sorted(arr, key=lambda x: (-freq[x], first_occurrence[x]))

    return sorted_arr

