def num_distinct(s: str, t: str) -> int:
    m, n = len(s), len(t)

    # Edge case: if t is empty, there's exactly one subsequence (empty string)
    if n == 0:
        return 1

    # Edge case: if s is empty and t is not, return 0
    if m == 0:
        return 0

    # Initialize a DP table with (m+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: there is 1 way to form an empty subsequence
    for i in range(m + 1):
        dp[i][0] = 1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # If characters match, we can take the value from dp[i-1][j-1] (current match)
            # and dp[i-1][j] (not taking the current character from s)
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                # If they don't match, just carry forward the previous value
                dp[i][j] = dp[i - 1][j]

    return dp[m][n]

