def longest_increasing_rainfall(rainfall):
    if not rainfall:
        return []

    # Initialize variables to track the longest increasing sequence
    max_length = 1
    current_length = 1
    start_index = 0
    max_start_index = 0

    for i in range(1, len(rainfall)):
        if rainfall[i] > rainfall[i - 1]:
            current_length += 1
            if current_length > max_length:
                max_length = current_length
                max_start_index = start_index
        else:
            current_length = 1
            start_index = i

    # Extract the subsequence from the original list
    return rainfall[max_start_index : max_start_index + max_length]

