def isSumOfTwoSquares(N):
    # We need to check if there exist distinct non-zero integers a and b such that a^2 + b^2 = N
    # Let's iterate over possible values of a from 1 to sqrt(N)
    # For each a, check if (N - a^2) is a perfect square and different from a^2

    import math

    for a in range(1, int(math.isqrt(N)) + 1):
        b_squared = N - a * a
        if b_squared <= 0:
            continue
        b = int(math.isqrt(b_squared))
        if b * b == b_squared and b != a:
            return True
    return False

