from collections import defaultdict, deque

def getProjectOrder(n, dependencies):
    # Step 1: Build the adjacency list and in-degree count
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)  # Projects are numbered from 1 to n

    for a, b in dependencies:
        graph[b].append(a)  # b is a prerequisite for a
        in_degree[a] += 1

    # Step 2: Initialize the queue with nodes that have no incoming edges
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []

    # Step 3: Process nodes in topological order
    while queue:
        current = queue.popleft()
        result.append(current)

        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Step 4: Check if we processed all projects (no cycle)
    if len(result) != n:
        return []  # Cycle detected

    return result

