def tsp(n, t):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(mask, pos):
        if mask == (1 << n) - 1:
            return t[pos][0]  # Return to city 0

        min_time = float('inf')
        for next_city in range(n):
            if not (mask & (1 << next_city)):
                new_mask = mask | (1 << next_city)
                min_time = min(min_time, t[pos][next_city] + dfs(new_mask, next_city))
        return min_time

    return dfs(1 << 0, 0)

