def group_attendees(preferences: List[str], group_size: int) -> List[List[str]]:
    if group_size <= 0:
        raise ValueError("Group size must be a positive integer.")

    # Count the occurrences of each preference
    preference_counts = defaultdict(int)
    for pref in preferences:
        preference_counts[pref] += 1

    # Create groups based on preferences
    groups = []
    for pref, count in preference_counts.items():
        # Create multiple groups if count exceeds group_size
        num_full_groups = count // group_size
        remainder = count % group_size

        # Add full groups
        for _ in range(num_full_groups):
            groups.append([pref] * group_size)

        # Add a group for the remainder if it's not zero
        if remainder > 0:
            groups.append([pref] * remainder)

    # If there are any preferences with zero count (unlikely in this case)
    for pref in preferences:
        if not any(pref in group for group in groups):
            groups.append([pref])  # Add to a new group if not placed

