def contains_all_distinct_subarray(nums, k):
    n = len(nums)

    # If the length of nums is less than k, it's impossible to have a subarray of length k
    if n < k:
        return "No"

    # Check each subarray of length k
    for i in range(n - k + 1):
        subarray = nums[i:i + k]
        # Check if all elements are distinct and in the range [1, k]
        if len(set(subarray)) == k and all(1 <= x <= k for x in subarray):
            return "Yes"

    return "No"

