from typing import List

def can_sum(nums: List[int], target: int) -> bool:
    if target == 0:
        return True
    if not nums or target < 0:
        return False

    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 can always be achieved

    for i in range(1, target + 1):
        for num in nums:
            if i >= num and dp[i - num]:
                dp[i] = True
                break  # No need to check other nums once a valid combination is found
    return dp[target]

