from typing import List
import heapq

def trapRainWater(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Push all the boundary cells into the heap
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (grid[i][j], i, j))
                visited[i][j] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    trapped_water = 0

    while heap:
        height, x, y = heapq.heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                # If the neighbor's height is less than the current boundary height,
                # water can be trapped
                if grid[nx][ny] < height:
                    trapped_water += height - grid[nx][ny]
                # Push the neighbor into the heap with its height
                heapq.heappush(heap, (max(height, grid[nx][ny]), nx, ny))

    return trapped_water

