def unique_paths_with_obstacles(grid):
    n = len(grid)
    m = len(grid[0])

    # If the starting or ending cell is blocked
    if grid[0][0] == 'X' or grid[n-1][m-1] == 'X':
        return 0

    # Initialize a DP table
    dp = [[0 for _ in range(m)] for _ in range(n)]
    dp[0][0] = 1  # Starting point

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == '.':
            dp[0][j] = dp[0][j-1]
        else:
            break  # Obstacle found, no further paths in this row

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == '.':
            dp[i][0] = dp[i-1][0]
        else:
            break  # Obstacle found, no further paths in this column

    # Fill the rest of the table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '.':
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Obstacle, no path through this cell

    return dp[n-1][m-1]

