def count_paths(labyrinth):
    N = len(labyrinth)

    # Check if entrance or exit is a wall
    if labyrinth[0][0] == '#' or labyrinth[N-1][N-1] == '#':
        return 0

    # Initialize DP table
    dp = [[0] * N for _ in range(N)]
    dp[0][0] = 1  # Starting point

    # Fill first row
    for j in range(1, N):
        if labyrinth[0][j] == '.':
            dp[0][j] = dp[0][j-1]
        else:
            break  # Can't go further right if there's a wall

    # Fill first column
    for i in range(1, N):
        if labyrinth[i][0] == '.':
            dp[i][0] = dp[i-1][0]
        else:
            break  # Can't go further down if there's a wall

    # Fill the rest of the DP table
    for i in range(1, N):
        for j in range(1, N):
            if labyrinth[i][j] == '.':
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Wall, no path through here

    return dp[N-1][N-1]

