def number_of_partitions(n):
    # Initialize a dp array where dp[i] will hold the number of partitions of i
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: one way to partition 0

    # Iterate over all possible integers k from 1 to n
    for k in range(1, n + 1):
        # Update dp[i] for all i >= k
        for i in range(k, n + 1):
            dp[i] += dp[i - k]

    return dp[n]

