def find_peaks(matrix):
    if not matrix or not matrix[0]:
        return []

    rows = len(matrix)
    cols = len(matrix[0])
    peaks = []

    for i in range(rows):
        for j in range(cols):
            # Check up
            if i > 0 and matrix[i][j] < matrix[i - 1][j]:
                continue
            # Check down
            if i < rows - 1 and matrix[i][j] < matrix[i + 1][j]:
                continue
            # Check left
            if j > 0 and matrix[i][j] < matrix[i][j - 1]:
                continue
            # Check right
            if j < cols - 1 and matrix[i][j] < matrix[i][j + 1]:
                continue
            # If all checks passed, it's a peak
            peaks.append((i, j))

    return peaks

