def num_paths_through_garden(N, M, garden):
    # If the start or end cell is a tree, no path is possible
    if garden[0][0] == 'T' or garden[N-1][M-1] == 'T':
        return 0

    # Initialize a DP table with the same dimensions as the garden
    dp = [[0] * M for _ in range(N)]
    dp[0][0] = 1  # Starting point has 1 way to reach itself

    # Fill the DP table
    for i in range(N):
        for j in range(M):
            if garden[i][j] == 'T':
                dp[i][j] = 0  # Trees cannot be passed through
                continue
            if i == 0 and j == 0:
                continue  # Already initialized
            if i == 0:  # First row, can only come from the left
                dp[i][j] = dp[i][j-1]
            elif j == 0:  # First column, can only come from above
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[N-1][M-1]

