def shuffle_string(s, indices):
    # Create a list of characters from the string
    chars = list(s)

    # Create a new list to hold the shuffled characters
    shuffled = [''] * len(s)

    # Shuffle the characters based on the indices
    for i, idx in enumerate(indices):
        shuffled[idx] = chars[i]

    # Join the list into a string and return
    return ''.join(shuffled)

