def max_subarray_length(nums: List[int], k: int) -> int:
    prefix_sum_map = {}
    prefix_sum = 0
    max_length = 0

    for i, num in enumerate(nums):
        prefix_sum += num

        # If prefix_sum is exactly k, update max_length
        if prefix_sum == k:
            max_length = i + 1

        # Check if (prefix_sum - k) exists in the map
        if (prefix_sum - k) in prefix_sum_map:
            max_length = max(max_length, i - prefix_sum_map[prefix_sum - k])

        # Store the first occurrence of this prefix_sum
        if prefix_sum not in prefix_sum_map:
            prefix_sum_map[prefix_sum] = i

    return max_length

