def max_non_overlapping_meetings(meetings: list[tuple[int, int]]) -> int:
    # Sort meetings based on their end times
    meetings.sort(key=lambda x: x[1])

    count = 0
    last_end = -1  # Initialize to a value before any possible start time

    for start, end in meetings:
        if start >= last_end:
            count += 1
            last_end = end

    return count

