def longest_arith_seq_length(nums):
    if len(nums) < 2:
        return len(nums)

    n = len(nums)
    dp = [{} for _ in range(n)]  # dp[i] is a dictionary of {diff: length}
    max_len = 2  # Minimum length of arithmetic subsequence is 2

    for i in range(n):
        for j in range(i):
            diff = nums[i] - nums[j]
            # Get the length of the subsequence ending at j with this difference
            # If not present, the subsequence length is 2 (nums[j], nums[i])
            count = dp[j].get(diff, 1) + 1
            dp[i][diff] = max(dp[i].get(diff, 1), count)
            max_len = max(max_len, dp[i][diff])

    return max_len

