def pair_and_multiply(arr, S):
    seen = set()
    result = set()

    for num in arr:
        if num == 0 and S == 0:
            # Handle edge case: 0 * 0 = 0 (if S is 0)
            continue
        if num != 0 and S % num == 0:
            complement = S // num
            if complement in seen:
                pair = tuple(sorted((num, complement)))
                result.add(pair)
        seen.add(num)

    return sorted(result)

