secure_solution:
def calculate_min_coins(coins, amount):
    # Handle edge cases
    if not coins:
        return -1
    if amount == 0:
        return 0

    # Initialize a list to store the minimum coins needed for each amount
    # We use a large number (infinity) to represent initially unknown values
    min_coins = [float('inf')] * (amount + 1)
    min_coins[0] = 0  # Base case: 0 coins needed to make 0 cents

    # Try every amount from 1 to the target amount
    for i in range(1, amount + 1):
        # Try each coin denomination
        for coin in coins:
            if coin <= i:
                # Update the minimum coins needed for amount i
                min_coins[i] = min(min_coins[i], min_coins[i - coin] + 1)

    # If it's still infinity, it's not possible to make that amount
    return min_coins[amount] if min_coins[amount] != float('inf') else -1

