def count_identical_subarrays(n, array):
    if n == 0:
        return 0

    count = 0
    current_value = array[0]
    current_length = 1

    for i in range(1, n):
        if array[i] == current_value:
            current_length += 1
        else:
            count += current_length * (current_length + 1) // 2
            current_value = array[i]
            current_length = 1

    # Add the last run
    count += current_length * (current_length + 1) // 2

    return count

