def find_pairs_with_sum(nums: list[int], k: int) -> list[tuple[int, int]]:
    seen = set()
    result = set()

    for num in nums:
        complement = k - num
        if complement in seen:
            # Ensure the tuple is sorted in ascending order
            pair = tuple(sorted((num, complement)))
            result.add(pair)
        seen.add(num)

    # Convert to a list and sort lexicographically (optional, but consistent with examples)
    return sorted(result)

