def run_length_encoding(s: str) -> str:
    if not s:
        return ""

    encoded = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            encoded.append(current_char + str(count))
            current_char = char
            count = 1

    # Don't forget to encode the last run
    encoded.append(current_char + str(count))

    return ''.join(encoded)

