def filter_and_sort_records(records: list[dict], filter_field: str, substring: str, sort_field: str) -> list[dict]:
    # Check if filter_field is present in any record
    if not any(filter_field in record for record in records):
        raise ValueError("Invalid field name provided.")

    # Check if sort_field is present in any record
    if not any(sort_field in record for record in records):
        raise ValueError("Invalid field name provided.")

    # Filter records containing the substring in filter_field
    filtered_records = [
        record for record in records
        if isinstance(record[filter_field], str) and substring in record[filter_field]
    ]

    # If no records match the substring, return an empty list
    if not filtered_records:
        return []

    # Sort the filtered records by sort_field
    # If sort_field values are strings, sort lexicographically; if numeric, sort numerically
    try:
        filtered_records.sort(key=lambda x: x[sort_field])
    except TypeError:
        # If comparison fails (e.g., mixing strings and numbers), convert to string for lexicographical sort
        filtered_records.sort(key=lambda x: str(x[sort_field]))

    return filtered_records

