def find_triplet(arr):
    n = len(arr)
    if n < 3:
        return False  # Not enough elements to form a triplet

    # Arrays to store the minimum element from the left and right
    left_min = [0] * n
    right_min = [0] * n

    # Fill left_min: minimum element from the start to current index
    left_min[0] = arr[0]
    for i in range(1, n):
        left_min[i] = min(left_min[i - 1], arr[i])

    # Fill right_min: minimum element from the end to current index
    right_min[n - 1] = arr[n - 1]
    for i in range(n - 2, -1, -1):
        right_min[i] = min(right_min[i + 1], arr[i])

    # Check for each element if it can be the middle element of a triplet
    for i in range(1, n - 1):
        if left_min[i - 1] < arr[i] and right_min[i + 1] < arr[i]:
            return True

    return False

