def count_valid_ways(N):
    if N == 0:
        return 0
    if N == 1:
        return 2  # "A" or "B"

    # Initialize base cases
    a_prev = 2  # For N = 1, sequences ending with one flower
    b_prev = 0  # For N = 1, no sequence can end with two flowers

    for i in range(2, N + 1):
        a_curr = (a_prev + b_prev)
        b_curr = a_prev
        a_prev, b_prev = a_curr, b_curr

    return a_prev + b_prev

