MOD = 10**9 + 7

def count_distinct_solutions(n, k):
    if n < 0 or k < 1:
        return 0
    if n == 0:
        return 1

    # Precompute factorials and inverse factorials up to n + k - 1
    max_val = n + k - 1
    fact = [1] * (max_val + 1)
    inv_fact = [1] * (max_val + 1)

    for i in range(1, max_val + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Fermat's little theorem to compute inverse of fact
    inv_fact[max_val] = pow(fact[max_val], MOD - 2, MOD)
    for i in range(max_val - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    # Compute binomial coefficient C(n + k - 1, k - 1)
    if k - 1 > n + k - 1:
        return 0
    return fact[n + k - 1] * inv_fact[k - 1] % MOD * inv_fact[n] % MOD

