def min_palindromic_substrings(s: str) -> int:
    n = len(s)
    # dp[i] = min number of palindromic substrings for s[0:i]
    dp = [0] + [float('inf')] * n  # dp[0] = 0 (empty string)

    # Precompute palindromic table: is_pal[i][j] is True if s[i:j+1] is a palindrome
    is_pal = [[False] * n for _ in range(n)]

    # All single characters are palindromes
    for i in range(n):
        is_pal[i][i] = True

    # Fill the is_pal table for substrings of length >= 2
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    is_pal[i][j] = True
                else:
                    is_pal[i][j] = is_pal[i + 1][j - 1]

    # Compute dp
    for i in range(1, n + 1):
        for j in range(i):
            if is_pal[j][i - 1]:
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n]

