def max_total_score(n, M, problems):
    # Initialize dp array where dp[t] means the max score obtainable with t minutes
    dp = [0] * (M + 1)

    for score, time in problems:
        # Traverse the dp array in reverse to prevent reusing the same item multiple times
        for t in range(M, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + score)

