def sum_divisible_by_x_or_y(nums, x, y):
    # Create a set of distinct elements from nums
    distinct_nums = set(nums)

    # Calculate the sum of elements divisible by either x or y
    total_sum = 0
    for num in distinct_nums:
        if num % x == 0 or num % y == 0:
            total_sum += num

    # If no such elements exist, return -1 for all
    if total_sum == 0:
        return [-1] * len(nums)

    # Otherwise, return the total_sum for all positions
    return [total_sum] * len(nums)

