from typing import List
import string

def count_anagram_pairs(words: List[str]) -> int:
    # Type validation
    if not isinstance(words, list):
        raise TypeError("Input must be a list.")

    for word in words:
        if not isinstance(word, str):
            raise TypeError("All elements in the list must be strings.")
        if not word:
            raise ValueError("Empty string is not allowed.")
        if not all(char in string.ascii_lowercase for char in word):
            raise ValueError("All characters in a string must be lowercase alphabets.")

    # Normalize each word to its sorted character string
    from collections import defaultdict

    anagram_counts = defaultdict(int)
    for word in words:
        normalized = ''.join(sorted(word))
        anagram_counts[normalized] += 1

    # Count the number of anagram pairs
    total_pairs = 0
    for count in anagram_counts.values():
        if count >= 2:
            total_pairs += count * (count - 1) // 2

    return total_pairs

