from datetime import datetime
from typing import List

def calculate_max_time_gap(timestamps: List[str]) -> float:
    max_gap = 0.0

    # Parse timestamps into datetime objects
    datetime_objects = [
        datetime.strptime(ts, "%Y-%m-%d %H:%M:%S.%f")
        for ts in timestamps
    ]

    # Calculate the gap between each pair of consecutive timestamps
    for i in range(1, len(datetime_objects)):
        gap = (datetime_objects[i] - datetime_objects[i - 1]).total_seconds()
        if gap > max_gap:
            max_gap = gap

    # Return the result with 6 decimal places
    return round(max_gap, 6)

