import heapq

def dijkstra(num_cities, roads, start, end):
    # Build the graph as an adjacency list
    graph = {i: [] for i in range(1, num_cities + 1)}
    for a, b, c in roads:
        graph[a].append((b, c))
        graph[b].append((a, c))

    # Priority queue: (distance, city)
    pq = [(0, start)]
    # Distance dictionary: city -> shortest distance from start
    distances = {i: float('inf') for i in range(1, num_cities + 1)}
    distances[start] = 0

    while pq:
        current_dist, current_city = heapq.heappop(pq)

        # If we've reached the destination, return the distance
        if current_city == end:
            return current_dist

        # Skip if we've found a shorter path to this city already
        if current_dist > distances[current_city]:
            continue

        # Explore neighbors
        for neighbor, weight in graph[current_city]:
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    # If no path was found
    return -1

