def length_of_longest_unique_substring(s):
    max_length = 0
    start = 0
    char_set = set()

    for end in range(len(s)):
        if s[end].isalnum():
            while s[end] in char_set:
                char_set.remove(s[start])
                start += 1
            char_set.add(s[end])
            max_length = max(max_length, end - start + 1)
        else:
            # Reset on encountering a space
            char_set.clear()
            start = end + 1

    return max_length

