def lenOfLongContSubstr(s):
    if not s:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(s)):
        # Check if current character's case matches the previous character
        if (s[i].islower() and s[i-1].islower()) or (s[i].isupper() and s[i-1].isupper()):
            current_len += 1
            max_len = max(max_len, current_len)
        else:
            current_len = 1

    return max_len

