def min_trucks_needed(n, weights, max_weight):
    # Sort the weights in ascending order
    weights.sort()

    trucks = 1
    current_weight = 0

    for weight in weights:
        if current_weight + weight > max_weight:
            # Start a new truck
            trucks += 1
            current_weight = weight
        else:
            current_weight += weight

    return trucks

