def rotate_array(arr: list, k: int) -> list:
    if not arr:
        return arr

    n = len(arr)
    k = k % n  # Adjust k to be within the range [0, n-1]

    if k == 0:
        return arr

    # Rotate the array in-place using slicing
    arr[:] = arr[-k:] + arr[:-k]
    return arr

