def pyramid_info(height):
    # Calculate the total sum of all numbers in the pyramid
    total_sum = sum(level * level for level in range(1, height + 1))

    # Calculate the product of the last level's numbers
    last_level_product = pow(height, height)

    return (total_sum, last_level_product)

def min_coins_to_make_change(N, amounts):
    max_amount = max(amounts) if amounts else 0
    # Initialize a list to store the minimum number of coins needed for each amount
    dp = [float('inf')] * (max_amount + 1)
    dp[0] = 0  # Base case: 0 coins needed to make 0

    # Denominations
    denominations = [1, 3, 5]

    # Compute the min coins for each amount from 1 to max_amount
    for amount in range(1, max_amount + 1):
        for coin in denominations:
            if coin <= amount:
                dp[amount] = min(dp[amount], dp[amount - coin] + 1)

    # Now, for each input amount, return the result or -1 if not possible
    results = []
    for m in amounts:
        if dp[m] == float('inf'):
            results.append(-1)
        else:
            results.append(dp[m])
    return results

