def longest_common_prefix(paths):
    if not paths:
        return ""

    # Start with the first path as the initial prefix
    prefix = paths[0]

    for path in paths[1:]:
        # While the current prefix is not a prefix of the current path, shorten it
        while not path.startswith(prefix):
            # Remove the last directory from the prefix
            prefix = prefix.rsplit('/', 1)[0]
            # If prefix becomes empty, no common prefix exists
            if not prefix:
                return ""

    return prefix

