def longest_subsequence(seq):
    if not seq:
        return 0

    n = len(seq)
    inc = [1] * n  # Longest increasing subsequence ending at each index
    dec = [1] * n  # Longest decreasing subsequence ending at each index

    for i in range(n):
        for j in range(i):
            if seq[i] > seq[j]:
                inc[i] = max(inc[i], inc[j] + 1)
            elif seq[i] < seq[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    return max(max(inc), max(dec))

