def minimum_tax_after_one_cut(n, heights):
    if n <= 1:
        return 0  # Not applicable as per constraints (n ≥ 2)

    first_max = second_max = 0

    for height in heights:
        if height > first_max:
            second_max = first_max
            first_max = height
        elif height > second_max:
            second_max = height

    # If there is more than one tree with max height
    count_max = 0
    for height in heights:
