from typing import List

def max_loot(houses: List[int]) -> int:
    if not houses:
        return 0
    if len(houses) == 1:
        return houses[0]

    prev_prev = houses[0]
    prev = max(houses[0], houses[1])

    for i in range(2, len(houses)):
        current = max(prev, prev_prev + houses[i])
        prev_prev, prev = prev, current

    return prev

