def recommend_shows(
    user_history: dict,
    target_user: str,
    all_shows: list,
    num_recommendations: int = 5
) -> list:
    # Get the shows that the target user has already watched
    target_watched = set(user_history.get(target_user, []))

    # List of all available shows that the target has *not* watched yet
    candidate_shows = [show for show in all_shows if show not in target_watched]

    # If there are no candidate shows, return an empty list
    if not candidate_shows:
        return []

    # Dictionary to score candidate shows based on how many similar users watched them
    show_scores = {}

    # Find users who share at least one show with the target user
    similar_users = []
    for user, shows in user_history.items():
        if user != target_user:
            common_shows = set(shows) & target_watched
            if common_shows:
                similar_users.append(user)

    # Score candidate shows based on how many similar users have watched them
    for show in candidate_shows:
        score = 0
        for user in similar_users:
            if show in user_history[user]:
                score += 1
        show_scores[show] = score

    # If no similar users, just return available shows that the user hasn't seen
    if not show_scores:
        return candidate_shows[:num_recommendations]

    # Sort the shows by score in descending order
    sorted_shows = sorted(show_scores, key=show_scores.get, reverse=True)

    # Return the top num_recommendations shows, or fewer if not available
    return sorted_shows[:num_recommendations]

