def unique_paths_with_obstacles(n, m, obstacles):
    # Convert obstacles to a set of tuples for O(1) lookups
    obstacle_set = set((x - 1, y - 1) for x, y in obstacles)  # Convert to 0-based index

    # Initialize DP table with dimensions (n x m)
    dp = [[0] * m for _ in range(n)]

    # Starting point
    if (0, 0) not in obstacle_set:
        dp[0][0] = 1

    # Fill the DP table
    for i in range(n):
        for j in range(m):
            if (i, j) in obstacle_set:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]

    return dp[n - 1][m - 1]

