def max_water_stations(n, k, distances):
    if n == 0:
        return 0

    # Sort the distances in increasing order
    distances.sort()

    count = 1  # We can always place a station at the first checkpoint
    last_position = distances[0]

    for i in range(1, n):
        if distances[i] - last_position >= k:
            count += 1
            last_position = distances[i]

    return count

