    prizes = [1] * N  # Every student gets at least 1 prize

    # Left to right pass
    for i in range(1, N):
        if problems[i] > problems[i - 1]:
            prizes[i] = prizes[i - 1] + 1

    # Right to left pass
    for i in range(N - 2, -1, -1):
