def trap_rain_water(elevation):
    if not elevation or len(elevation) < 3:
        return 0

    left, right = 0, len(elevation) - 1
    max_left, max_right = elevation[left], elevation[right]
    trapped_water = 0

    while left < right:
        if elevation[left] < elevation[right]:
            if elevation[left] >= max_left:
                max_left = elevation[left]
            else:
                trapped_water += max_left - elevation[left]
            left += 1
        else:
            if elevation[right] >= max_right:
                max_right = elevation[right]
            else:
                trapped_water += max_right - elevation[right]
            right -= 1

    return trapped_water

