    # Calculate the sum of each row
    row_sums = [sum(row) for row in matrix]

    # Calculate the sum of each column
    col_sums = [sum(matrix[row][col] for row in range(n)) for col in range(m)]

    # Check if there exists a row whose sum is greater than all column sums
    for row_sum in row_sums:
        if all(row_sum > col_sum for col_sum in col_sums):
            return "YES"

    return "NO"

