def min_difference(tasks):
    total_sum = sum(tasks)
    n = len(tasks)

    # Use a set to keep track of achievable sums
    possible_sums = {0}

    for task in tasks:
        new_sums = set()
        for s in possible_sums:
            new_sums.add(s)
            new_sums.add(s + task)
        possible_sums = new_sums

    # Find the sum closest to total_sum / 2
    closest = 0
    for s in possible_sums:
        if abs(s - total_sum / 2) < abs(closest - total_sum / 2):
            closest = s

    return total_sum - 2 * closest

