        for s in possible_sums:
            new_sums.add(s)
            new_sums.add(s + task)
        possible_sums = new_sums

    # Find the sum closest to total_sum / 2
    closest = 0
    for s in possible_sums:
        if abs(s - total_sum / 2) < abs(closest - total_sum / 2):
            closest = s

    return total_sum - 2 * closest

