def min_trees_to_plant(n, grid):
    rows_with_tree = [False] * n
    cols_with_tree = [False] * n

    # Mark which rows and columns have trees
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'T':
                rows_with_tree[i] = True
                cols_with_tree[j] = True

    # Count rows and columns without trees
    rows_without = sum(1 for r in rows_with_tree if not r)
    cols_without = sum(1 for c in cols_with_tree if not c)

    # To cover all missing rows and columns, the minimum is min(rows_without, cols_without)
    # But if rows_without and cols_without are different, the remaining ones need to be covered
    return max(rows_without, cols_without)

