def has_triplet_with_sum(nums, target):
    nums.sort()  # Sort the list to use the two-pointer technique
    n = len(nums)

    for i in range(n - 2):  # Iterate through the first element of the triplet
        left = i + 1         # Start of the remaining list
        right = n - 1        # End of the remaining list

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]

            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1  # Need a larger sum, move left pointer to the right
            else:
                right -= 1  # Need a smaller sum, move right pointer to the left

    return False

