def largest_common_substring(str1: str, str2: str) -> str:
    m, n = len(str1), len(str2)
    # dp[i][j] will store the length of the longest common substring ending at str1[i-1] and str2[j-1]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    max_length = 0  # Length of the longest common substring found
    end_index = 0   # Ending index of the longest common substring in str1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > max_length:
                    max_length = dp[i][j]
                    end_index = i  # Update end index in str1
            else:
                dp[i][j] = 0  # Reset since the substring breaks here

    # Extract the longest common substring
    return str1[end_index - max_length:end_index]

