from collections import deque

def count_possible_teams(N, K, D, S):
    max_deque = deque()
    min_deque = deque()
    count = 0

    for i in range(N):
        # Remove elements out of the current window from the front
        while max_deque and max_deque[0] < i - K + 1:
            max_deque.popleft()
        while min_deque and min_deque[0] < i - K + 1:
            min_deque.popleft()

        # Maintain max_deque: elements are in decreasing order
        while max_deque and S[max_deque[-1]] <= S[i]:
            max_deque.pop()
        max_deque.append(i)

        # Maintain min_deque: elements are in increasing order
        while min_deque and S[min_deque[-1]] >= S[i]:
            min_deque.pop()
        min_deque.append(i)

        # Once the window size is at least K, check the condition
        if i >= K - 1:
            if S[max_deque[0]] - S[min_deque[0]] <= D:
                count += 1

    return count

