def max_gold_coins(m, n, grid):
    # Initialize DP table
    dp = [[0] * n for _ in range(m)]

    # Initialize the first column with the grid values
    for i in range(m):
        dp[i][0] = grid[i][0]

    # Process each column from the second to the last
    for j in range(1, n):
        for i in range(m):
            # Check the possible cells from the previous column
            max_prev = 0
            for di in [-1, 0, 1]:
                ni = i + di
                if 0 <= ni < m:
                    max_prev = max(max_prev, dp[ni][j - 1])
            dp[i][j] = max_prev + grid[i][j]

    # The result is the maximum value in the last column
    return max(dp[i][n - 1] for i in range(m))

