def minimize_array_lexicographically(arr, k):
    n = len(arr)
    for i in range(n):
        if k <= 0:
            break
        # Find the smallest element in arr[i:]
        min_index = i
        for j in range(i, n):
            if arr[j] < arr[min_index]:
                min_index = j
        # If the smallest element is not already at position i
        if min_index != i:
            # Reverse the subarray from i to min_index
            arr[i:min_index+1] = arr[i:min_index+1][::-1]
            k -= 1
    return arr

