def most_frequent_badge_holder(n, m, events):
    # Initialize a list to count badges for each user
    badge_counts = [0] * (n + 1)  # Index 0 is unused since user IDs are 1-based

    # Count the number of badges for each user
    for user_id in events:
        badge_counts[user_id] += 1

    # Find the maximum number of badges
    max_badges = max(badge_counts)

    # Find the user with the smallest ID who has max_badges
    for user_id in range(1, n + 1):
        if badge_counts[user_id] == max_badges:
            return user_id

def unique_paths_with_trees(n, m, grid):
    # Convert the grid to a list of lists of integers for easier processing
    grid = [[1 if cell == '1' else 0 for cell in row] for row in grid]

    # If the start or end cell is not a tree, return -1
    if grid[0][0] == 0 or grid[n-1][m-1] == 0:
        return -1

    # Initialize DP table
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    # Fill DP table
    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                continue  # already initialized
            if grid[i][j] == 0:
                continue  # skip cells without trees
            # Add number of ways from top and left
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1] if dp[n-1][m-1] > 0 else -1

