import json

def csv_to_json(csv_data):
    # Split the CSV data into lines
    lines = csv_data.strip().split('\n')

    if not lines:
        raise ValueError("CSV data is invalid: No data provided.")

    # Split the first line into headers
    headers = [header.strip() for header in lines[0].split(',')]

    # Check that all subsequent lines have the same number of columns
    for line in lines[1:]:
        fields = line.split(',')
        if len(fields) != len(headers):
            raise ValueError("CSV data is invalid: Rows have inconsistent number of columns.")

    # Parse the remaining lines into a list of dictionaries
    result = []
    for line in lines[1:]:
        fields = [field.strip() for field in line.split(',')]
        result.append(dict(zip(headers, fields)))

    # Convert the list of dictionaries to a JSON string
    return json.dumps(result)

