def max_projects(N, B, budgets):
    # Sort the budgets in ascending order
    budgets.sort()

    count = 0
    total = 0

    for budget in budgets:
        if total + budget <= B:
            total += budget
            count += 1
        else:
            break  # No more projects can be funded without exceeding the budget

    return count

