def checkValidString(s: str) -> bool:
    if not isinstance(s, str):
        raise ValueError("Invalid character found in the input string")

    # Check for invalid characters
    if any(c not in '()*' for c in s):
        raise ValueError("Invalid character found in the input string")

    low = 0
    high = 0

    for c in s:
        if c == '(':
            low += 1
            high += 1
        elif c == ')':
            low -= 1
            high -= 1
        elif c == '*':
            low -= 1
            high += 1

        # If at any point high < 0, it means too many closing parentheses
        if high < 0:
            return False

        # If low < 0, reset to 0 (since * can act as closing parenthesis)
        if low < 0:
            low = 0

    return low == 0

