def min_partition_diff(n, weights):
    total_weight = sum(weights)
    min_diff = float('inf')

    # Try all possible subsets using bitmasking
    for mask in range(1 << n):  # 1 << n is 2^n
        subset_sum = 0
        for i in range(n):
            if (mask >> i) & 1:
                subset_sum += weights[i]
        current_diff = abs(total_weight - 2 * subset_sum)
        if current_diff < min_diff:
            min_diff = current_diff

    return min_diff

