import heapq

def find_min_traffic_path(matrix):
    if not matrix or not matrix[0]:
        return 0

    n = len(matrix)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    visited = [[False] * n for _ in range(n)]
    min_heap = [(matrix[0][0], 0, 0)]  # (traffic_sum, row, col)
    distances = [[float('inf')] * n for _ in range(n)]
    distances[0][0] = matrix[0][0]

    while min_heap:
        traffic, row, col = heapq.heappop(min_heap)

        if row == n - 1 and col == n - 1:
            return traffic

        if visited[row][col]:
            continue

        visited[row][col] = True

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n and not visited[new_row][new_col]:
                new_traffic = traffic + matrix[new_row][new_col]
                if new_traffic < distances[new_row][new_col]:
                    distances[new_row][new_col] = new_traffic
                    heapq.heappush(min_heap, (new_traffic, new_row, new_col))

    return -1  # Should not reach here if matrix is valid

