def min_moves_to_sort_deck(n, cards):
    # Map each card value to its index in the input to get the positions
    pos = {card: i for i, card in enumerate(cards)}

    # Extract positions in the order of the values from 1 to n
    sequence = [pos[i] for i in range(1, n + 1)]

