def get_lexicographical_smallest_permutation(nums, k):
    n = len(nums)
    for i in range(n):
        # Find the minimum element in the range [i, min(i + k, n - 1)]
        min_idx = i
        for j in range(i + 1, min(i + k + 1, n)):
            if nums[j] < nums[min_idx]:
                min_idx = j
        # Bring the minimum element to position i using adjacent swaps
        for j in range(min_idx, i, -1):
            nums[j], nums[j - 1] = nums[j - 1], nums[j]
        # Decrease k by the number of swaps performed
        k -= (min_idx - i)
        if k <= 0:
            break
    return nums

