def minRemoveToMakeValid(s):
    stack = []
    to_remove = set()

    # First pass: Track unmatched closing parentheses
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        elif ch == ')':
            if stack:
                stack.pop()
            else:
                to_remove.add(i)

    # Second pass: Track unmatched opening parentheses
    while stack:
        to_remove.add(stack.pop())

    # Build the result string
    result = []
    for i, ch in enumerate(s):
        if i not in to_remove:
            result.append(ch)

    return ''.join(result)

