def can_sort_by_reversals(nums, k):
    # Check if the array is already sorted
    is_sorted = True
    for i in range(len(nums) - 1):
        if nums[i] > nums[i + 1]:
            is_sorted = False
            break

    if is_sorted:
        # If array is already sorted, we can use k reversals (even if they are redundant)
        return True

    # If array is not sorted, we need at least 1 reversal
    # And we need exactly k reversals, so check if k >= 1
    return k >= 1

