def find_max_consecutive_ones(nums):
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(len(nums)):
        if nums[right] == 0:
            zero_count += 1

        # If there are more than one zero, move the left pointer to the right
        while zero_count > 1:
            if nums[left] == 0:
                zero_count -= 1
            left += 1

        # Update the maximum window size
        max_length = max(max_length, right - left + 1)

    return max_length

