def can_partition(nums):
    total_sum = sum(nums)

    # If the total sum is odd, partition is not possible
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2
    n = len(nums)

    # Create a boolean DP array where dp[i] indicates if a subset with sum i can be formed
    dp = [False] * (target_sum + 1)
    dp[0] = True  # Base case: zero sum can always be formed

    # Update the dp array
    for num in nums:
        for j in range(target_sum, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    return dp[target_sum]

