from collections import deque
from typing import List

def min_jumps(h: List[int], k: int) -> int:
    n = len(h)
    if n == 0:
        return -1
    if n == 1:
        return 0

    visited = [False] * n
    queue = deque([(0, 0)])  # (current_index, jumps)
    visited[0] = True

    while queue:
        index, jumps = queue.popleft()

        # We can jump up to k buildings ahead
        for i in range(index + 1, min(index + k + 1, n)):
            if h[i] >= h[index] and not visited[i]:
                if i == n - 1:
                    return jumps + 1
                visited[i] = True
                queue.append((i, jumps + 1))

    return -1

