    results = []

    for test_case in test_cases:
        N, arr = test_case
        max_len = 1  # Minimum length is 1 (single element)
        current_len = 1

        for i in range(1, N):
            # Check if current and previous elements have different parity
            if (arr[i] % 2) != (arr[i - 1] % 2):
                current_len += 1
                max_len = max(max_len, current_len)
            else:
                current_len = 1  # Reset the counter if parity is same

        results.append(max_len)

    return results

