def shortest_path_k_edges(n, m, k, edges):
    import sys
    import heapq

    # Initialize the DP table with infinity
    INF = float('inf')
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][1] = 0  # Starting at vertex 1 with 0 edges used

    # Build an adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))  # Undirected graph

    # Iterate over the number of edges used (from 1 to k)
    for step in range(1, k + 1):
        for u in range(1, n + 1):
            if dp[step - 1][u] == INF:
                continue  # Skip unreachable nodes
            for v, w in graph[u]:
                if dp[step][v] > dp[step - 1][u] + w:
                    dp[step][v] = dp[step - 1][u] + w

    return dp[k][n] if dp[k][n] != INF else -1

