def knapsack(maxWeight, weights, values):
    # Initialize dp array with size maxWeight + 1
    dp = [0] * (maxWeight + 1)

    # Iterate through each item
    for i in range(len(weights)):
        # Update dp in reverse to prevent reusing the same item
        for w in range(maxWeight, weights[i] - 1, -1):
            dp[w] = max(dp[w], dp[w - weights[i]] + values[i])

    # The maximum value that can be achieved is in dp[maxWeight]
    return dp[maxWeight]

