def max_books(n, h, hours):
    # Sort the reading times to prioritize shorter books
    hours.sort()

    total = 0
    count = 0

    # Greedily select the shortest books first
    for time in hours:
        if total + time <= h:
            total += time
            count += 1
        else:
            break  # No more books can be added without exceeding the limit

    return count

