def find_pairs(nums, target):
    seen = set()
    result = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            # Create a sorted tuple to avoid duplicates like (a, b) and (b, a)
            pair = tuple(sorted((num, complement)))
            result.add(pair)
        seen.add(num)

    # Convert the result set to a sorted list of tuples
    return sorted(result)

