def min_insertions_to_palindrome(s):
    n = len(s)

    # Function to compute the length of the longest palindromic subsequence
    def lps(i, j):
        if i > j:
            return 0
        if i == j:
            return 1
        if s[i] == s[j]:
            return 2 + lps(i + 1, j - 1)
        else:
            return max(lps(i + 1, j), lps(i, j - 1))

    # Minimum insertions needed = length of string - length of LPS
    return n - lps(0, n - 1)

