def can_travel_between_floors(n, m, q, elevator_ranges, queries):
    # Step 1: Build the graph (adjacency list)
    graph = [[] for _ in range(n + 1)]  # floors 1 to n

    for ai, bi in elevator_ranges:
        # All floors from ai to bi are connected to each other
        for u in range(ai, bi + 1):
            for v in range(ai, bi + 1):
                if u != v:
                    graph[u].append(v)

    # Step 2: Process each query
    results = []
    for si, ti in queries:
        if si == ti:
            results.append("YES")
            continue

        # BFS to check if ti is reachable from si
        visited = set()
        queue = deque([si])
        visited.add(si)
        found = False

        while queue:
            current = queue.popleft()
            if current == ti:
                found = True
                break
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        results.append("YES" if found else "NO")

    return results

