def max_apples(nums):
    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]

    # Initialize previous two values
    prev_prev = nums[0]
    prev = max(nums[0], nums[1])

    for i in range(2, len(nums)):
        current = max(prev, prev_prev + nums[i])
        prev_prev, prev = prev, current

    return prev

