secure_solution:
def smallest_unique_substring(l, s):
    n = len(s)
    min_substring = None

    # Check all substrings of length l
    for i in range(n - l + 1):
        substring = s[i:i + l]
        # Check if all characters in the substring are unique
        if len(set(substring)) == l:
            # Update the minimum lexicographical substring
            if min_substring is None or substring < min_substring:
                min_substring = substring

    return min_substring if min_substring is not None else "-1"

