from typing import List

def search_books_by_prefix(titles: List[str], prefix: str) -> List[str]:
    def starts_with_prefix(title: str) -> bool:
        return title.startswith(prefix)

    def find_first_index(left: int, right: int) -> int:
        while left <= right:
            mid = (left + right) // 2
            if starts_with_prefix(titles[mid]):
                if mid == 0 or not starts_with_prefix(titles[mid - 1]):
                    return mid
                else:
                    right = mid - 1
            elif titles[mid] < prefix:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    def find_last_index(left: int, right: int) -> int:
        while left <= right:
            mid = (left + right) // 2
            if starts_with_prefix(titles[mid]):
                if mid == len(titles) - 1 or not starts_with_prefix(titles[mid + 1]):
                    return mid
                else:
                    left = mid + 1
            elif titles[mid] < prefix:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    first_index = find_first_index(0, len(titles) - 1)
    if first_index == -1:
        return []

    last_index = find_last_index(first_index, len(titles) - 1)
    return titles[first_index:last_index + 1]

