def max_money(days):
    if not days:
        return 0
    n = len(days)
    if n == 1:
        return days[0]

    # Initialize dp array
    dp = [0] * n
    dp[0] = days[0]
    dp[1] = max(days[0], days[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + days[i])

    return dp[-1]

