def reverse_parentheses(s: str) -> str:
    stack = []
    current_str = ""

    for char in s:
        if char == '(':
            stack.append(current_str)
            current_str = ""
        elif char == ')':
            popped = stack.pop()
            current_str = popped + current_str[::-1]
        else:
            current_str += char

    return current_str

