def max_subgrid_sum(grid, n, k):
    # Create a prefix sum matrix
    prefix = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the prefix sum matrix
    for i in range(n):
        for j in range(n):
            prefix[i+1][j+1] = grid[i][j] + prefix[i][j+1] + prefix[i+1][j] - prefix[i][j]

    max_sum = float('-inf')

    # Iterate over all possible k x k subgrids
    for i in range(n - k + 1):
        for j in range(n - k + 1):
            # Calculate the sum of the subgrid using the prefix sum matrix
            current_sum = prefix[i + k][j + k] - prefix[i][j + k] - prefix[i + k][j] + prefix[i][j]
            max_sum = max(max_sum, current_sum)

    return max_sum

def unique_paths_with_trees(M, N, park):
    # Initialize a DP table with the same dimensions as the park
    dp = [[0] * N for _ in range(M)]

    # If the starting cell is blocked, no path is possible
    if park[0][0] == 1:
        return 0

    # Base case: Only one way to reach the starting cell
    dp[0][0] = 1

    # Fill the DP table
    for i in range(M):
        for j in range(N):
            if park[i][j] == 1:
                dp[i][j] = 0  # Tree, can't pass through
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]  # From above
                if j > 0:
                    dp[i][j] += dp[i][j-1]  # From the left

    return dp[M-1][N-1]

